import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/app.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (1, 'admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (2, 'svc-reader', 'reader@corp.internal', 'readonly', 'sk-read-1a2b3c4d')")
    db.commit()
    db.close()

@app.before_request
def authenticate():
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'missing api key'}), 401
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
    if not user:
        return jsonify({'error': 'invalid api key'}), 403
    g.current_user = dict(user)

@app.route('/api/users/search')
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Restrict searchable fields to prevent information disclosure
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid search field'}), 400

    # Build query - field is validated above so safe to interpolate
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except sqlite3.Error as e:
        db.execute("INSERT INTO audit_log (action) VALUES (?)", (f"query_error:{str(e)}",))
        db.commit()
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/users/<int:user_id>')
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/api/me')
def get_me():
    return jsonify({
        'username': g.current_user['username'],
        'email': g.current_user['email'],
        'role': g.current_user['role']
    })

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    debug_mode = os.environ.get('FLASK_DEBUG', '0') == '1'
    app.run(host='0.0.0.0', port=8080, debug=debug_mode)
